\label{thm:main}
The optimal constants satisfy
\begin{align}
 C_s
 &\leq (18\pi)^{1/3}
 =\left(\frac{8}{3\pi}\right)^{1/3}
   \frac32\lvert \mathbb{S}^3\rvert^{1/3}
 <\frac32\lvert \mathbb{S}^3\rvert^{1/3},
 \label{eq:main-Cs}\\
 C_v
 &\leq C_v^{\mathcal{T}}
 \leq 2\left(\frac{80\pi^2}{49}\right)^{1/3}
 =2\left(\frac{40}{49}\right)^{1/3}\lvert \mathbb{S}^3\rvert^{1/3}
 <2\lvert \mathbb{S}^3\rvert^{1/3}.
 \label{eq:main-Cv}
\end{align}
Equivalently,
\begin{equation}\label{eq:main-power}
 S_{3/2,\mathrm{curl}}
 \leq S_{3/2,\mathrm{curl}}^{\mathcal{T}}
 \leq \frac{8\sqrt{10}}7\pi
 <4\pi.
\end{equation}
Consequently, neither $\psi_{\mathrm{LY}}$ nor $A_{\mathrm{LY}}$ is a global
optimizer of its respective inequality.

\label{lem:gauge}
Let $n\geq2$, $1<q<\infty$, and $A\in L^q(\mathbb{R}^n;\mathbb{R}^n)$. If
\begin{equation}\label{eq:nonlinear-gauge-q}
 \nabla\cdot(\lvert A\rvert^{q-2}A)=0
\end{equation}
in the sense of distributions, then
\[
 \inf_{\phi\in\dot W^{1,q}(\mathbb{R}^n)}\lVert A-\nabla\phi\rVert_{q}
 =\lVert A\rVert_{q}.
\]

Let $\eta\in\mathbb{C}^2$ be a constant unit spinor and let
$0\neq u\in L^3(\mathbb{R}^3;\mathbb{R})$ be weakly differentiable with
$\nabla u\in L^{3/2}(\mathbb{R}^3;\mathbb{R}^3)$. For $\psi=u\eta\in\mathcal{X}_s$ one has, almost
everywhere,
\begin{equation*}
 \lvert \boldsymbol{\sigma}\cdot(-i\nabla)\psi\rvert=\lvert \nabla u\rvert.
\end{equation*}
Consequently,
\begin{equation*}
 \frac{\lVert \boldsymbol{\sigma}\cdot(-i\nabla)\psi\rVert_{3/2}}
      {\lVert \psi\rVert_{3}}
 =\frac{\lVert \nabla u\rVert_{3/2}}{\lVert u\rVert_{3}}.
\end{equation*}

\label{thm:FL-spinor-all-d}
For every integer $d\geq2$, define
\begin{align}
 I_d^{\mathrm{AT}}
 &:=\frac{\lvert \mathbb{S}^{d-1}\rvert}{q_d}
 \mathrm B\left(\frac{d-1}{2},\frac{d+1}{2}\right),
 \notag\\
 I_d^{\mathrm{FL}}
 &:=\frac{\lvert \mathbb{S}^{d-1}\rvert}{2}
 \mathrm B\left(\frac d2,\frac d2\right)
 =\frac{\pi^{d/2}\Gamma(d/2)}{\Gamma(d)}
 =\frac{\lvert \mathbb{S}^d\rvert}{2^d}.
 \label{eq:I-FL-d}
\end{align}
Then the constant-direction spinor
\begin{equation}\label{eq:AT-spinor-d}
 \psi_d(x):=u_d(x)\eta,
 \qquad
 u_d(x):=(1+\lvert x\rvert^{q_d})^{-(d-1)/2},
 \qquad \lvert \eta\rvert=1,
\end{equation}
satisfies
\begin{equation}\label{eq:AT-quotient-d}
 \mathcal Q_d(\psi_d)
 =d^{p_d}(I_d^{\mathrm{AT}})^{2/(d+1)}.
\end{equation}
Every spinor in \eqref{eq:FL-family-10-d}--\eqref{eq:FL-family-conditions-d}
satisfies
\begin{equation}\label{eq:FL-quotient-d}
 \mathcal Q_d(\Psi_{\phi_0,\phi_1})
 =d^{p_d}(I_d^{\mathrm{FL}})^{2/(d+1)}.
\end{equation}
Moreover,
\begin{equation}\label{eq:integral-ratio-d}
 \frac{I_d^{\mathrm{AT}}}{I_d^{\mathrm{FL}}}
 =\frac{(d-1)^2}{2d}
 \left(\frac{\Gamma((d-1)/2)}{\Gamma(d/2)}\right)^2
 <1.
\end{equation}
Consequently,
\begin{equation}\label{eq:FL-disproof-d}
 S_d^s
 \leq d^{p_d}(I_d^{\mathrm{AT}})^{2/(d+1)}
 <d^{p_d}(I_d^{\mathrm{FL}})^{2/(d+1)},
\end{equation}
and no nonzero spinor in the family \cite[formula (10)]{FrankLossSharp} is an
optimizer of \eqref{eq:FL-sharp-spinor-general}.

\label{thm:FL-vector-all-d}
For every integer $d\geq3$, the field $A_{\mathcal{T},d}$ belongs to $Y_d$ and
satisfies
\begin{equation}\label{eq:vector-trial-gauge-d}
 \nabla\cdot(\lvert A_{\mathcal{T},d}\rvert^{d-2}A_{\mathcal{T},d})=0,
 \qquad
 \VERT A_{\mathcal{T},d}\VERT_{d}=\lVert A_{\mathcal{T},d}\rVert_{L^d}.
\end{equation}
Let
\begin{equation}\label{eq:Gd-bd}
 G_d:=\frac{\Gamma(1+d/2)\Gamma((d+1)/2)}{\Gamma(d+1/2)}
     =\frac{2^d}{\binom{2d}{d}},
 \qquad
 b_d:=\frac{2(d-1)}{3d-2}.
\end{equation}
Then
\begin{equation}\label{eq:vector-trial-Ld-d}
 \int_{\mathbb{R}^d}\lvert A_{\mathcal{T},d}\rvert^d\,\mathrm{d} x
 =d^d\,2^{-2d}\lvert \mathbb{S}^d\rvert G_d.
\end{equation}
\begin{equation}\label{eq:vector-trial-energy-d}
 \int_{\mathbb{R}^d}\lvert \nabla\wedge A_{\mathcal{T},d}\rvert^{d/2}\,\mathrm{d} x
 =(2d)^{d/2}2^{-d}\lvert \mathbb{S}^d\rvert b_d,
\end{equation}
and consequently
\begin{align}
 \mathcal Q_d^v(A_{\mathcal{T},d})
 &=2^{d/2}\lvert \mathbb{S}^d\rvert^{1/2}\frac{b_d}{\sqrt{G_d}},
 \label{eq:vector-trial-powered-d}\\
 R_d^v(A_{\mathcal{T},d})
 &=2\lvert \mathbb{S}^d\rvert^{1/d}
   \left(\frac{4(d-1)^2}{(3d-2)^2G_d}\right)^{1/d}.
 \label{eq:vector-trial-unpowered-d}
\end{align}
Moreover,
\begin{equation}\label{eq:Theta-d}
 \frac{R_d^v(A_{\mathcal{T},d})}
      {\sqrt{2(d-1)}\lvert \mathbb{S}^d\rvert^{1/d}}
 =:\Theta_d
 =\left[
   \frac{4\binom{2d}{d}(d-1)^2}
   {(3d-2)^2[2(d-1)]^{d/2}}
   \right]^{1/d}<1.
\end{equation}
In particular,
\begin{equation*}
 S_d^v
 \leq2^{d/2}\lvert \mathbb{S}^d\rvert^{1/2}\frac{b_d}{\sqrt{G_d}},
 \qquad d\geq3,
\end{equation*}
and, for every odd $d\geq3$,
\begin{equation*}
 S_d^v
 \leq\mathcal Q_d^v(A_{\mathcal{T},d})
 <[2(d-1)]^{d/4}\lvert \mathbb{S}^d\rvert^{1/2}
 =\mathcal Q_d^v(A_{\mathrm{LYDM},d}).
\end{equation*}
Hence, in every odd dimension, no nonzero scalar multiple of a conformal
pullback of the Loss--Yau--Dunne--Min potential, with or without an added
$L^d$ gradient, is an optimizer of the Frank--Loss vector inequality.
